225: function conformanceAuthorityMatches(
226:   call: Parameters<
227:     ExactDefinitionCallable<
228:       ConformanceContract,
229:       ConformanceEvaluationResourceAssertion,
230:       ConformanceEvaluationResourceAssertion
231:     >
232:   >[0],
233:   artifactTruth: ExactPrefixArtifactTruthProjection,
234: ): boolean {
235:   const slots = call.invocation.invocationAuthority.slots;
236:   if (
237:     !isRecord(slots.workspace_binding) ||
238:     !isRecord(slots.dependency_lock) ||
239:     !Array.isArray(slots.product_set) ||
240:     !isRecord(slots.actor) ||
241:     !isRecord(slots.actor.actor)
242:   ) return false;
243:   const bindingRow = artifactTruth.rows.find((row) =>
244:     row.operationId === "abg.operation.workspace.bind" &&
245:     row.artifactRef === slots.workspace_binding!.ref &&
246:     row.artifactDigest === slots.workspace_binding!.digest
247:   );
248:   if (
249:     bindingRow === undefined ||
250:     !isWorkspaceAuthorityBasis(bindingRow.workspaceAuthorityBasis) ||
251:     slots.actor.actor.ref !==
252:       bindingRow.workspaceAuthorityBasis.authorizedActorRef
253:   ) return false;
254:   const installs = bindingRow.causationEventRefs.map((eventRef) =>
255:     projectAdmittedProductInstallByAdmissionEventRef(artifactTruth, eventRef)
256:   );
257:   if (installs.length === 0 || installs.some((install) => install === null)) {
258:     return false;
259:   }
260:   const lock = installs[0]!.resolvedLock;
261:   if (
262:     installs.some((install) => !sameJson(install!.resolvedLock, lock)) ||
263:     !sameCoordinate(slots.dependency_lock, {
264:       ref: lock.lockId,
265:       digest: lock.lockDigest,
266:     }) ||
267:     !exactCoordinateSet(
268:       slots.product_set,
269:       installs.map((install) => productInstallCoordinate(install!.install)),
270:     )
271:   ) return false;
272:   const binding = projectAdmittedWorkspaceBindingByInvocationRef(
273:     artifactTruth,
274:     bindingRow.invocationRef,
275:     lock,
276:   );
277:   return binding !== null &&
278:     binding.binding.bindingId === slots.workspace_binding.ref &&
279:     binding.binding.bindingDigest === slots.workspace_binding.digest;
280: }
