282: function reconstructDeclarationBasis(
283:   resources: ConformanceEvaluationResourceAssertion,
284:   environment: ExactPrefixWorkspaceEnvironment,
285: ): ConformanceDeclarationBasis {
286:   const supplied = resources.declarationCatalog;
287:   if (!isRecord(supplied) || !hasExactKeys(supplied, ["catalog", "catalogView"])) {
288:     throw new TypeError("declared inventory requires its exact admitted catalog and view");
289:   }
290:   const installs = environment.productInstalls.map(install =>
291:     projectAdmittedProductInstallByAdmissionEventRef(environment.artifactTruth, install.admissionEventRef));
292:   if (installs.some(install => install === null)) {
293:     throw new TypeError("conformance artifact truth differs from its exact admitted environment");
294:   }
295:   const { catalog, catalogView } = reconstructHistoricalDeclarationCatalog(supplied, {
296:     workspaceBinding: environment.workspaceBindingCandidate,
297:     resolvedLock: environment.resolvedProductLock,
298:     installedProducts: installs.map((install) => install!.candidate),
299:   });
300:   if (
301:       !exactCoordinateSet(catalog.boundPublications.map(publication => reference(publication.moduleRef,
302:         sha256Canonical(publication as unknown as JsonValue))).sort(compareCoordinates),
303:       resources.declaredInventory.map(publication => reference(publication.moduleRef,
304:         sha256Canonical(publication as unknown as JsonValue))).sort(compareCoordinates))) {
305:     throw new TypeError("conformance inventory differs from its admitted workspace, installs, lock or publication owners");
306:   }
307:   const declarationClosure = resolveProgramDeclarationClosure(catalog, catalogView, resources.packet.program.programRef);
308:   if (declarationClosure.kind !== "resolved_program_declaration_closure" ||
309:       !sameJson(declarationClosure.programPublication, resources.packet.publication)) {
310:     throw new TypeError("conformance Program has no exact compatible declaration owner closure");
311:   }

