315: const gtl_program = (
316:   call: DefinitionCall<ConformanceContract, ConformanceEvaluationResourceAssertion>,
317:   boundEnvironment: ExactPrefixWorkspaceEnvironment | null,
318: ) => Effect.try({
319:   try: (): DefinitionReturn<
320:     ConformanceContract,
321:     ConformanceEvaluationResourceReceipt
322:   > => {
323:     // withAdmissionAuthority has already canonicalized these exact resources
324:     // for the approved digest, including the existing finite-JSON check;
325:     // repeating a self-comparison here would serialize the entire body twice.
326:     const resources = call.resources;
327:     if (
328:       !isRecord(resources) ||
329:       !hasExactKeys(resources, [
330:         "conformanceLaw",
331:         "declaredInventory",
332:         "kind",
333:         "packet",
334:         "schemaVersion",
335:         ...(Object.hasOwn(resources, "declarationCatalog") ? ["declarationCatalog"] : []),
336:       ]) ||
337:       resources.kind !== "conformance_evaluation_resource_assertion" ||
338:       resources.schemaVersion !== "5.0.0" ||
339:       !isRecord(resources.packet) ||
340:       !isRecord(resources.conformanceLaw) ||
341:       !Array.isArray(resources.declaredInventory) ||
342:       resources.declaredInventory.length === 0
343:     ) {
344:       throw fault(
345:         call.invocation.definitionKey,
346:         "invalid_resource_assertion",
347:         "GTL Program conformance requires one exact typed publication and Program packet",
348:       );
349:     }
350:     const request = call.invocation.request;
351:     const packet = resources.packet;
352:     if (!exactDefinitionCallMatches(
353:       call,
354:       CONFORMANCE_OPERATION_CONTRACTS.evaluate.gtl_program,
355:     )) {
356:       throw fault(
357:         call.invocation.definitionKey,
358:         "call_identity_mismatch",
359:         "conformance call differs from its fixed definition, contracts, request digest, or authority topology",
360:       );
361:     }
362:     const program = reference(
363:       packet.program.programRef,
364:       sha256Canonical(packet.program as unknown as JsonValue),
365:     );
366:     const publication = reference(
367:       packet.publication.moduleRef,
368:       sha256Canonical(packet.publication as unknown as JsonValue),
369:     );
370:     const inventory = resources.declaredInventory.map((entry) => {
371:       const canonical = canonicalizeAuthoredGtlCarrier(
372:         entry,
373:         "module_publication",
374:       );
375:       if (!sameJson(canonical, entry)) {
376:         throw fault(
377:           call.invocation.definitionKey,
378:           "invalid_resource_assertion",
379:           "declared inventory contains a noncanonical Module publication",
380:         );
381:       }
382:       return reference(
383:         entry.moduleRef,
384:         sha256Canonical(entry as unknown as JsonValue),
385:       );
386:     }).sort(compareCoordinates);
387:     const requestedInventory = request.inventoryBasis.kind ===
388:         "declared_inventory"
389:       ? canonicalCoordinateSet(request.inventoryBasis.inventory)
390:       : null;
391:     const inventoryMatches = request.inventoryBasis.kind === "program_only" ||
392:       (inventory.length === new Set(inventory.map(({ ref }) => ref)).size &&
393:         requestedInventory !== null &&
394:         exactCoordinateSet(requestedInventory, inventory) &&
395:         inventory.some((coordinate) => sameCoordinate(coordinate, publication)));
396:     if (
397:       packet.kind !== "conformance_evaluate_packet" ||
398:       packet.schemaVersion !== "5.0.0" ||
399:       packet.memberKey !== "gtl_program" ||
400:       !sameCoordinate(request.program, program) ||
401:       !sameCoordinate(request.conformanceLaw, resources.conformanceLaw) ||
402:       !inventoryMatches ||
403:       boundEnvironment === null ||
404:       // Grant construction awaited archive verification. Recheck the physical
405:       // prefix at this owner boundary while borrowing its completed derivation.
406:       !validateExactPrefixArtifactTruthProjection(boundEnvironment.artifactTruth, { requireCurrent: true }) ||
407:       !conformanceAuthorityMatches(call, boundEnvironment.artifactTruth)
408:     ) {
409:       throw fault(
410:         call.invocation.definitionKey,
411:         "resource_relation_mismatch",
412:         "conformance packet differs from the public Program, law, or inventory coordinates",
413:       );
414:     }
415:     if (!sameCoordinate(request.conformanceLaw, GTL_PROGRAM_CONFORMANCE_LAW)) {
416:       return deepFreeze({
417:         ownerOutput: lawMismatchRefusal(),
418:         resources: resourceReceipt(call),
419:       });
420:     }
421:     let declarationBasis: ConformanceDeclarationBasis | undefined;
422:     try {
423:       if (request.inventoryBasis.kind === "declared_inventory") {
424:         declarationBasis = reconstructDeclarationBasis(resources, boundEnvironment);
425:       } else if (resources.declarationCatalog !== undefined) {
426:         throw new TypeError("program_only conformance does not consume a declaration catalog");
427:       }
428:     } catch (cause) {
429:       throw fault(call.invocation.definitionKey, "resource_relation_mismatch", String(cause));
430:     }
431:     const native = declarationBasis === undefined
432:       ? ConformancePort.evaluateGtlProgram(packet)
433:       : evaluateGtlProgramConformanceFromResolvedClosure(packet, declarationBasis.declarationClosure);
434:     if (native.disposition === "failed" && native.code !== "validation_failed") {
435:       return deepFreeze({
436:         ownerOutput: nativeRefusal(native),
437:         resources: resourceReceipt(call),
438:       });
439:     }
440:     const assessment = native.disposition === "passed"
441:       ? reference(native.evidenceRef, native.evidenceDigest)
442:       : reference(
443:         native.diagnosticRef,
444:         sha256Canonical(native as unknown as JsonValue),
445:       );

186: export function admitCapabilityEnvironment(
187:   value: unknown,
188:   acquiredResource: AcquiredAbgEventResource | null = null,
189:   requireCurrent = true,
190: ): ExactPrefixWorkspaceEnvironment {
191:   const selection = v.parse(admissionEnvironmentSelectionSchema, value);
192:   let prefix = selection.prefix;
193:   if (acquiredResource !== null) {
194:     assertHeldEventStoreAtDurablePrefix(acquiredResource.store, acquiredResource.entryPrefix);
195:     if (!sameJson(prefix, acquiredResource.entryPrefix))
196:       throw new TypeError("admission environment differs from the acquired current prefix");
197:     prefix = acquiredResource.entryPrefix;
198:   }
199:   const artifactTruth = projectOwnedPrefixArtifactTruth(prefix);
200:   if (artifactTruth.kind !== "exact_prefix_artifact_truth_projection")
201:     throw new TypeError("admission requires authenticated exact-prefix artifact truth");
202:   const environment = projectWorkspaceEnvironmentFromArtifactTruth(artifactTruth, selection.workspaceBinding);
203:   if (environment.kind !== "exact_prefix_workspace_environment")
204:     throw new TypeError("admission requires the exact admitted prefix environment");
205:   if (requireCurrent) assertDurableRuntimePrefixCurrent(environment.prefix);

296: export function withAdmissionAuthority<P extends OwnerContractSourceDeclaration, R, O>(
297:   packet: P,
298:   owner: AdmissionDefinitionOwner<P, R, O>,
299: ): ExactDefinitionCallable<P, AdmissionAuthorizedResources<R>, O> {
300:   return (call) => Effect.suspend(() => {
301:     let acquiredResource: AcquiredAbgEventResource | null = null;
302:     return Effect.tryPromise({
303:       try: async () => {
304:         if (admitExactDefinitionCall(call, packet) === null || !isRecord(call.resources)) {
305:           throw new TypeError("definition call differs from its fixed owner");
306:         }
307:         const parsed = v.parse(admissionAuthorityResourceStructure, call.resources.admissionAuthority);
308:         const { admissionAuthority: _authority, ...resources } = call.resources;
309:         if (!sameJson(parsed.basis.request, call.invocation.request) ||
310:             parsed.basis.resourceScope.resourcesDigest !== digest(resources) ||
311:             !sameJson(parsed.basis.resourceScope.authoritySlots, admissionAuthoritySlots(call.invocation.invocationAuthority.slots))) {
312:           throw new TypeError("admission resources differ from the approved request and authority scope");
313:         }
314:         // Bound reopened effects acquire once, before semantic reconstruction.
315:         // A new resource is still created only by its authorized effect owner.
316:         const assertion = (resources as Record<string, unknown>).eventResource;
317:         if (isAcquiredAbgEventResourceSelection(assertion) ||
318:             (parsed.basis.boundEnvironment !== null && isRecord(assertion) && assertion.kind === "reopen_abg_event_resource")) {
319:           if (!validateAbgEventResourceInput(assertion)) throw new TypeError("invalid event resource assertion");
320:           const acquired = acquireAbgEventResource(assertion);
321:           if (acquired.kind !== "acquired_abg_event_resource") throw definitionFault(
322:             packet.definitionKey, "resource_acquisition", acquired.code, acquired.message);
323:           acquiredResource = acquired.resource;
324:         }
325:         const { grants, boundEnvironment } = await constructAdmissionCapabilityGrants(
326:           parsed.authority, parsed.authority.actorRef,
327:           { kind: "admission_capability_grant_construction_basis", fixedPacket: packet, data: parsed.basis },
328:           acquiredResource,
329:         );
330:         if (!sameJson(parsed.grants, grants) || !sameJson(
331:           call.invocation.invocationAuthority.slots.capability_grants,
332:           { requiredCapabilityRefs: [...packet.metadata.capabilityRefs], grants: grants.map((grant) => ({ ref: grant.grantRef, digest: grant.grantDigest })) },
333:         )) throw new TypeError("admission grants differ from exact owner reconstruction");
334:         return { call: { ...call, resources: resources as R }, boundEnvironment };
335:       },
336:       catch: (cause) => definitionFault(packet.definitionKey, "resource_admission", "resource_relation_mismatch", String(cause)),
337:     }).pipe(
338:       Effect.flatMap(({ call, boundEnvironment }) => owner(call, boundEnvironment, acquiredResource)),
339:       // An owner may refuse before entering its effect scope. Release the same
340:       // acquisition in every outcome; ordinary owner close still issues truth.
341:       Effect.ensuring(Effect.sync(() => { if (acquiredResource !== null) abandonAbgEventResource(acquiredResource); })),
342:     );
343:   });
